module std_mem_d3_32_16_16_16_4_4_4 #(
    parameter WIDTH = 32,
    parameter D0_SIZE = 16,
    parameter D1_SIZE = 16,
    parameter D2_SIZE = 16,
    parameter D0_IDX_SIZE = 4,
    parameter D1_IDX_SIZE = 4,
    parameter D2_IDX_SIZE = 4
) (
   input wire                logic [D0_IDX_SIZE-1:0] addr0,
   input wire                logic [D1_IDX_SIZE-1:0] addr1,
   input wire                logic [D2_IDX_SIZE-1:0] addr2,
   input wire                logic [ WIDTH-1:0] write_data,
   input wire                logic write_en,
   input wire                logic clk,
   output logic [ WIDTH-1:0] read_data,
   output logic              done
);
logic [ WIDTH-1:0] mem [0:D0_SIZE-1][0:D1_SIZE-1][0:D2_SIZE-1];
   always_comb begin
      if (addr0 >= D0_SIZE) begin
         $display("Error: std_mem_d3_32_16_16_16_4_4_4: addr0 out of bounds");
         $finish;
      end
      if (addr1 >= D1_SIZE) begin
         $display("Error: std_mem_d3_32_16_16_16_4_4_4: addr1 out of bounds");
         $finish;
      end
      if (addr2 >= D2_SIZE) begin
         $display("Error: std_mem_d3_32_16_16_16_4_4_4: addr2 out of bounds");
         $finish;
      end
      read_data = mem[addr0][addr1][addr2];
   end
   always_ff @(posedge clk) begin
      if (write_en) begin
         mem[addr0][addr1][addr2] <= write_data;
         done <= 1;
      end
      else begin
         done <= 0;
      end
   end
endmodule

