module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [19:0] counter;
    reg [1:0] index;
    reg [9:0] keypress_array[0:10] = {10{10'd0}};
    initial begin
        keypress_array[0] = 10'd1;
        keypress_array[1] = 10'd2;
        keypress_array[2] = 10'd3;
        keypress_array[3] = 10'd4;
        keypress_array[4] = 10'd5;
        keypress_array[5] = 10'd6;
        keypress_array[6] = 10'd7;
        keypress_array[7] = 10'd8;
        keypress_array[8] = 10'd9;
        keypress_array[9] = 10'd10;
    end
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            index <= 0;
            keypress <= 0;
        end
        else begin
            if (counter == 20) begin
                counter <= 0;
                index <= index + 1;
                if (index == 10) begin
                    index <= 0;
                end
                keypress <= keypress_array[index];
            end
            else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

