module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [WIDTH-1:0] dat0, dat1;
logic [2:0] state;
always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
		dat0 <= {WIDTH{1'b0}};
		dat1 <= {WIDTH{1'b0}};
	end else begin
		case (state)
			S0: begin
				if (t0_valid && i0_ready) begin
					dat0 <= t0_data;
					state <= S1;
				end
			end
			S1: begin
				if (t0_valid && i0_ready) begin
					dat1 <= t0_data;
					state <= S2;
				end
			end
			S2: begin
				if (t0_valid && i0_ready) begin
					dat0 <= t0_data;
					state <= S3;
				end
			end
			S3: begin
				if (t0_valid && i0_ready) begin
					dat1 <= t0_data;
					state <= S4;
				end
			end
			S4: begin
				if (t0_valid && i0_ready) begin
					dat0 <= t0_data;
					state <= S0;
				end
			end
		endcase
	end
end
assign t0_ready = (state == S0) ? i0_ready : 1'b0;
assign i0_data = (state == S0) ? dat0 : (state == S2) ? dat1 : {WIDTH{1'b0}};
assign i0_valid = (state != S0) ? 1'b1 : 1'b0;
endmodule

