endmodule

module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
);
parameter [31:0] TOTAL_PIXELS = 1024;
parameter [31:0] H_SYNC_PULSE = 96;
parameter [31:0] H_BLANK = 48;
parameter [31:0] V_SYNC_PULSE = 2;
parameter [31:0] V_BLANK = 10;
parameter [31:0] H_ACTIVE = 960;
parameter [31:0] V_ACTIVE = 540;
parameter [31:0] H_SYNC_START = 960;
parameter [31:0] H_SYNC_END = 960 + 96;
parameter [31:0] V_SYNC_START = 540;
parameter [31:0] V_SYNC_END = 540 + 2;
reg [9:0] h_counter;
reg [9:0] v_counter;
reg [9:0] h_sync_counter;
reg [9:0] v_sync_counter;
assign hsync = h_sync_counter < H_SYNC_PULSE;
assign vsync = v_sync_counter < V_SYNC_PULSE;
assign pixel_x = h_counter;
assign pixel_y = v_counter;
assign visible_region = h_counter < H_ACTIVE && v_counter < V_ACTIVE;
always @(posedge pixel_clk) begin
    if(h_counter == TOTAL_PIXELS - 1) begin
        h_counter <= 0;
        h_sync_counter <= 0;
    end
    else begin
        h_counter <= h_counter + 1;
        if(h_counter == H_SYNC_START) begin
            h_sync_counter <= 0;
        end
        else if(h_counter == H_SYNC_END) begin
            h_sync_counter <= H_SYNC_PULSE;
        end
        else if(h_counter == H_ACTIVE) begin
            h_sync_counter <= H_SYNC_PULSE + H_BLANK;
        end
        else begin
            h_sync_counter <= h_sync_counter + 1;
        end
    end
    if(v_counter == TOTAL_PIXELS - 1) begin
        v_counter <= 0;
        v_sync_counter <= 0;
    end
    else begin
        v_counter <= v_counter + 1;
        if(v_counter == V_SYNC_START) begin
            v_sync_counter <= 0;
        end
        else if(v_counter == V_SYNC_END) begin
            v_sync_counter <= V_SYNC_PULSE;
        end
        else if(v_counter == V_ACTIVE) begin
            v_sync_counter <= V_SYNC_PULSE + V_BLANK;
        end
        else begin
            v_sync_counter <= v_sync_counter + 1;
        end
    end
end
endmodule

