module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
); 

parameter [1:0] S_0 = 2'd0;
parameter [1:0] S_ED_T4 = 2'd1;
parameter [1:0] S_4D_T4 = 2'd2;
parameter [1:0] S_CB_T4 = 2'd3;
reg [1:0] state;
reg [1:0] next_state;
reg ifetch_d;
reg [7:0] cpu_opcode;
wire ifetch;
wire ifetch_cancel;
wire [1:0] decoded_opcode;
wire [1:0] next_state_decode;
wire [1:0] next_state_seen;
assign ifetch = i_mreq_n & i_iorq_n & i_rfsh_n;
assign ifetch_cancel = i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
assign decoded_opcode = cpu_opcode[7:4];
assign next_state_decode = (decoded_opcode == 2'b00) ? S_0 : (decoded_opcode == 2'b01) ? S_ED_T4 : (decoded_opcode == 2'b10) ? S_4D_T4 : (decoded_opcode == 2'b11) ? S_CB_T4 : 2'b00;
assign next_state_seen = (decoded_opcode == 2'b00) ? S_0 : (decoded_opcode == 2'b01) ? S_ED_T4 : (decoded_opcode == 2'b10) ? S_4D_T4 : (decoded_opcode == 2'b11) ? S_CB_T4 : 2'b00;
assign o_reti_decode = (state == S_ED_T4) ? 1'b1 : (state == S_4D_T4) ? 1'b1 : (state == S_CB_T4) ? 1'b1 : 1'b0;
assign o_reti_seen = (state == S_ED_T4) ? 1'b1 : (state == S_4D_T4) ? 1'b1 : (state == S_CB_T4) ? 1'b1 : 1'b0;
always @(posedge i_CLK_CPU or posedge i_reset) begin
  if (i_reset == 1'b1) begin
    state <= S_0;
  end else begin
    state <= next_state;
  end
end
always @(*) begin
  ifetch_d = ifetch;
  cpu_opcode = i_cpu_d;
  next_state = S_0;
  if (ifetch_d == 1'b1) begin
    if (ifetch_cancel == 1'b1) begin
      next_state = S_0;
    end else begin
      if (decoded_opcode == 2'b00) begin
        next_state = S_0;
      end else if (decoded_opcode == 2'b01) begin
        next_state = S_ED_T4;
      end else if (decoded_opcode == 2'b10) begin
        next_state = S_4D_T4;
      end else if (decoded_opcode == 2'b11) begin
        next_state = S_CB_T4;
      end
    end
  end
end
endmodule

