module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
parameter [1:0] IDLE = 2'b00,
              DATA0 = 2'b01,
              DATA1 = 2'b10;

  reg [1:0] state;
  reg [35:0] data0, data1;
  reg src0_rdy, src1_rdy;
  reg eof;

  always @(*) begin
    case (state)
      IDLE: begin
        src0_rdy = 1'b0;
        src1_rdy = 1'b0;
        data0 = 0;
        data1 = 0;
        eof = 1'b0;
      end
      DATA0: begin
        src0_rdy = 1'b1;
        src1_rdy = 1'b0;
        data0 = data_i;
        data1 = 0;
        eof = data_i[35];
      end
      DATA1: begin
        src0_rdy = 1'b0;
        src1_rdy = 1'b1;
        data0 = 0;
        data1 = data_i;
        eof = data_i[35];
      end
    endcase
  end

  always @(*) begin
    case (state)
      IDLE: begin
        dst_rdy_o = 1'b0;
        data0_o = 0;
        data1_o = 0;
        src0_rdy_o = 1'b0;
        src1_rdy_o = 1'b0;
      end
      DATA0: begin
        dst_rdy_o = dst0_rdy_i;
        data0_o = data0;
        data1_o = 0;
        src0_rdy_o = src0_rdy;
        src1_rdy_o = 1'b0;
      end
      DATA1: begin
        dst_rdy_o = dst1_rdy_i;
        data0_o = 0;
        data1_o = data1;
        src0_rdy_o = 1'b0;
        src1_rdy_o = src1_rdy;
      end
    endcase
  end

  always @(posedge clk or posedge reset or posedge clear) begin
    if (reset) begin
      state <= IDLE;
    end else if (clear) begin
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (src_rdy_i) begin
            if (data_i[35]) begin
              state <= DATA0;
            end else begin
              state <= DATA1;
            end
          end
        end
        DATA0: begin
          if (dst0_rdy_i) begin
            state <= IDLE;
          end
        end
        DATA1: begin
          if (dst1_rdy_i) begin
            state <= IDLE;
          end
        end
      endcase
    end
  end
endmodule

