module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [2:0] D_reg;
reg [2:0] A_reg;
reg WR_reg;
reg RD_reg;
reg [6:0] Y_reg;
reg [6:0] Y_next;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      D_reg <= 3'b000;
    end else begin
      D_reg <= D;
    end
    if((RST == 1'b1)) begin
      A_reg <= 3'b000;
    end else begin
      A_reg <= A;
    end
    if((RST == 1'b1)) begin
      WR_reg <= 1'b0;
    end else begin
      WR_reg <= WR;
    end
    if((RST == 1'b1)) begin
      RD_reg <= 1'b0;
    end else begin
      RD_reg <= RD;
    end
    if((RST == 1'b1)) begin
      Y_reg <= 7'b0000000;
    end else begin
      Y_reg <= Y_next;
    end
  end
  always @(D_reg, A_reg, WR_reg, RD_reg) begin
    if((RD_reg == 1'b1)) begin
      Y_next <= D_reg;
    end
    if((WR_reg == 1'b1)) begin
      Y_next <= D_reg;
    end
  end
  always @(Y_reg) begin
    WCTRL <= 1'b0;
    case((Y_reg))
    7'b0000000: begin
      WCTRL <= 1'b1;
    end
    7'b0000001: begin
      WCTRL <= 1'b1;
    end
    7'b0000010: begin
      WCTRL <= 1'b1;
    end
    7'b0000100: begin
      WCTRL <= 1'b1;
    end
    7'b0001000: begin
      WCTRL <= 1'b1;
    end
    7'b0010000: begin
      WCTRL <= 1'b1;
    end
    7'b0100000: begin
      WCTRL <= 1'b1;
    end
    7'b1000000: begin
      WCTRL <= 1'b1;
    end
    default: begin
      WCTRL <= 1'b0;
    end
    endcase
  end
  assign Y = Y_reg;
endmodule

