module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [10:0] H_ACTIVE = 1280;
parameter [10:0] H_FRONT_PORCH = 160;
parameter [10:0] H_BACK_PORCH = 160;
parameter [10:0] H_SYNC_PULSE = 96;
parameter [10:0] H_TOTAL = 1920;
parameter [10:0] V_ACTIVE = 720;
parameter [10:0] V_FRONT_PORCH = 20;
parameter [10:0] V_BACK_PORCH = 30;
parameter [10:0] V_SYNC_PULSE = 2;
parameter [10:0] V_TOTAL = 750;
reg [10:0] X;
reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
        X <= 11'b0000000000;
        Y <= 11'b0000000000;
        H_SYNC <= 1'b0;
        V_SYNC <= 1'b0;
        DISP_EN <= 1'b0;
    end else begin
        if(X < H_ACTIVE) begin
            X <= X + 1;
        end
        else begin
            X <= 11'b0000000000;
            if(Y < V_ACTIVE) begin
                Y <= Y + 1;
            end
            else begin
                Y <= 11'b0000000000;
            end
        end
        if(X < H_ACTIVE + H_FRONT_PORCH) begin
            H_SYNC <= 1'b0;
        end
        else if(X < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE) begin
            H_SYNC <= 1'b1;
        end
        else if(X < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH) begin
            H_SYNC <= 1'b0;
        end
        else begin
            H_SYNC <= 1'b0;
        end
        if(Y < V_ACTIVE + V_FRONT_PORCH) begin
            V_SYNC <= 1'b0;
        end
        else if(Y < V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE) begin
            V_SYNC <= 1'b1;
        end
        else if(Y < V_ACTIVE + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH) begin
            V_SYNC <= 1'b0;
        end
        else begin
            V_SYNC <= 1'b0;
        end
        if(X < H_ACTIVE + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH + H_TOTAL) begin
            DISP_EN <= 1'b1;
        end
        else begin
            DISP_EN <= 1'b0;
        end
    end
end
endmodule

