module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam ZERO = 2'b00;
    localparam ONE = 2'b01;
    localparam TWO = 2'b10;

    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                        load_p1 <= 1'b1;
                    end
                end
                ONE: begin
                    if (s_valid && m_ready) begin
                        state <= TWO;
                        load_p2 <= 1'b1;
                    end
                end
                TWO: begin
                    if (s_valid && m_ready) begin
                        state <= ZERO;
                        load_p1_from_p2 <= 1'b1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= s_data;
        end
        if (load_p1_from_p2) begin
            data_p1 <= data_p2;
        end
    end

    assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;
    assign m_valid = (state == TWO) ? 1'b1 : 1'b0;
    assign m_data = (state == TWO) ? data_p1 : data_p2;

endmodule

