module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
wire do_enq;
  wire do_deq;
  wire [3:0] maybe_full;
  assign do_enq = io_enq_ready & io_enq_valid;
  assign do_deq = io_deq_ready & io_deq_valid;
  assign io_enq_ready = ~do_enq;
  assign io_deq_valid = ~do_deq;
  assign io_deq_bits_tl_state_size = maybe_full;
  assign io_deq_bits_tl_state_source = 2'h0;
  always @(posedge clock) begin
    if (reset) begin
      maybe_full <= 4'h0;
    end else begin
      if (do_enq) begin
        maybe_full <= maybe_full + 4'h1;
      end
      if (do_deq) begin
        maybe_full <= maybe_full - 4'h1;
      end
    end
  end
endmodule

