module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [7:0] shift_reg;
    reg [3:0] counter;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 8'b0;
            counter <= 4'b0;
            dout_valid <= 1'b0;
        end else begin
            if (din_valid) begin
                shift_reg <= {din_serial, shift_reg[7:1]};
                counter <= counter + 1;
                if (counter == 8) begin
                    dout_valid <= 1'b1;
                    counter <= 4'b0;
                end
            end
            if (dout_valid) begin
                dout_parallel <= shift_reg;
                dout_valid <= 1'b0;
            end
        end
    end
endmodule

