module blake2_G(
                input wire [63 : 0]  a,
                input wire [63 : 0]  b,
                input wire [63 : 0]  c,
                input wire [63 : 0]  d,
                input wire [63 : 0]  m0,
                input wire [63 : 0]  m1,

                output wire [63 : 0] a_prim,
                output wire [63 : 0] b_prim,
                output wire [63 : 0] c_prim,
                output wire [63 : 0] d_prim
               );
reg [63:0] a0;
    reg [63:0] a1;
    reg [63:0] b0;
    reg [63:0] b1;
    reg [63:0] b2;
    reg [63:0] b3;
    reg [63:0] c0;
    reg [63:0] c1;
    reg [63:0] d0;
    reg [63:0] d1;
    reg [63:0] d2;
    reg [63:0] d3;

    always @* begin
        a0 = a + m0;
        a1 = a0 ^ m1;
        b0 = b + a1;
        b1 = b0 >> 32;
        b2 = b0 << 32;
        b3 = b1 ^ a1;
        c0 = c + b3;
        c1 = c0 >> 32;
        c2 = c0 << 32;
        c3 = c1 ^ b3;
        d0 = d + c3;
        d1 = d0 >> 32;
        d2 = d0 << 32;
        d3 = d1 ^ c3;
        a_prim = a0;
        b_prim = b0;
        c_prim = c0;
        d_prim = d0;
    end
endmodule

