module complexmulttrial(
input [15:0] a_r,
input [15:0] a_i,
input [15:0] b_r,
input [15:0] b_i,
input [15:0] w_r,
input [15:0] w_i,
output [15:0] x_r,
output [15:0] x_i,
output [15:0] y_r,
output [15:0] y_i);
wire [31:0] a_r1;
wire [31:0] a_i1;
wire [31:0] b_r1;
wire [31:0] b_i1;
wire [31:0] w_r1;
wire [31:0] w_i1;
wire [31:0] x_r1;
wire [31:0] x_i1;
wire [31:0] y_r1;
wire [31:0] y_i1;
assign a_r1 = a_r;
assign a_i1 = a_i;
assign b_r1 = b_r;
assign b_i1 = b_i;
assign w_r1 = w_r;
assign w_i1 = w_i;
assign x_r1 = a_r1 + b_r1;
assign x_i1 = a_i1 + b_i1;
assign y_r1 = (a_r1 - b_r1) * w_r1 - (a_i1 - b_i1) * w_i1;
assign y_i1 = (a_r1 - b_r1) * w_i1 + (a_i1 - b_i1) * w_r1;
assign x_r = x_r1[15:0];
assign x_i = x_i1[15:0];
assign y_r = y_r1[15:0];
assign y_i = y_i1[15:0];
endmodule

