module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
generate
    if (ASYNC == 0) begin
        reg [DATA_WIDTH-1:0] r_din;
        reg [DATA_WIDTH-1:0] r_dout;

        always @(posedge clk) begin
            r_din <= din;
            r_dout <= r_din << SHIFT_VALUE;
        end

        assign dout = r_dout;
    end
    else begin
        wire [DATA_WIDTH-1:0] c_din;
        wire [DATA_WIDTH-1:0] c_dout;

        assign c_din = din;
        assign c_dout = c_din << SHIFT_VALUE;

        assign dout = c_dout;
    end
endgenerate

generate
    if (DATA_TYPE == "signed") begin
        wire [DATA_WIDTH-1:0] c_dout;
        wire [DATA_WIDTH-1:0] c_dout_neg;
        wire [DATA_WIDTH-1:0] c_dout_pos;
        wire [DATA_WIDTH-1:0] c_dout_neg_overflow;
        wire [DATA_WIDTH-1:0] c_dout_pos_overflow;

        assign c_dout = c_dout_pos;
        assign c_dout_neg = c_dout_neg_overflow;
        assign c_dout_pos = c_dout_pos_overflow;

        assign c_dout_pos_overflow = c_dout_pos + 1;
        assign c_dout_neg_overflow = c_dout_neg - 1;

        assign c_dout_neg = {1'b0, c_dout_neg};
        assign c_dout_pos = {1'b1, c_dout_pos};

        assign warning[0] = c_dout_pos_overflow > c_dout;
        assign warning[1] = c_dout_neg_overflow < c_dout;
    end
    else begin
        wire [DATA_WIDTH-1:0] c_dout;
        wire [DATA_WIDTH-1:0] c_dout_overflow;

        assign c_dout = c_dout_overflow;
        assign c_dout_overflow = c_dout + 1;

        assign warning[0] = c_dout_overflow > c_dout;
    end
endgenerate

endmodule

