module full_adder_19(
input wire a,
input wire b,
input wire c,
output wire sum,
output wire carry
); 

assign sum = (c & ~a & ~b) | (~c & a & ~b) | (~c & ~a & b) | (c & a & b);
  assign carry = (c & a & b) | (~c & a & b);
endmodule

