module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @(*)
    begin
        case(m)
            3'b000: y = a + b;
            3'b001: y = a - b;
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            default: y = 0;
        endcase
        zf = y == 0;
        cf = y[WIDTH - 1] ^ a[WIDTH - 1] ^ b[WIDTH - 1];
        of = 0;
    end
endmodule

