module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 5.0;
    parameter C_L = 1.0;
    parameter t_hmin = 1.0;
    parameter t_hmax = 1.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR == 1'b0) begin
            Q <= 1'b0;
        end
        else begin
            Q <= D;
        end
        if (Q != Q) begin
            counter = counter + 1;
        end
        $display("Power dissipation: %d", counter * C_L * Vcc^2);
    end
endmodule

