module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
reg [31:0]step;
	reg [31:0]counter;
	reg auto_clk;
	reg wasReady;
	wire [31:0]auto_clk_reg;
	wire [31:0]step_reg;
	wire [31:0]counter_reg;
	wire [31:0]clkdiv_reg;
	wire [31:0]Clk_CPU_reg;
	wire [31:0]readn_reg;

	assign auto_clk_reg = {1'b0,step_reg[24],step_reg[4]};
	assign step_reg = {1'b0,step_reg[23:0],1'b0};
	assign counter_reg = {1'b0,counter_reg[23:0],1'b0};
	assign clkdiv_reg = {1'b0,clkdiv_reg[23:0],1'b0};
	assign Clk_CPU_reg = {1'b0,Clk_CPU_reg[23:0],1'b0};
	assign readn_reg = {1'b0,readn_reg[23:0],1'b0};

	always @(posedge clk or posedge rst) begin
		if(rst) begin
			step <= 0;
			counter <= 0;
			auto_clk <= 0;
			wasReady <= 0;
		end
		else begin
			if(SW2) begin
				if(SW15) begin
					if(keyReady) begin
						if(wasReady) begin
							if(BTN_OK[3]) begin
								step <= 1;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[2]) begin
								step <= 2;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[1]) begin
								step <= 4;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[0]) begin
								step <= 8;
								counter <= 0;
								wasReady <= 0;
							end
						end
						else begin
							if(counter == 0) begin
								counter <= 1;
								wasReady <= 1;
							end
							else begin
								counter <= counter + 1;
							end
						end
					end
					else begin
						if(counter == 0) begin
							counter <= 1;
						end
						else begin
							counter <= counter + 1;
						end
					end
				end
				else begin
					if(keyReady) begin
						if(wasReady) begin
							if(BTN_OK[3]) begin
								step <= 1;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[2]) begin
								step <= 2;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[1]) begin
								step <= 4;
								counter <= 0;
								wasReady <= 0;
							end
							else if(BTN_OK[0]) begin
								step <= 8;
								counter <= 0;
								wasReady <= 0;
							end
						end
						else begin
							if(counter == 0) begin
								counter <= 1;
								wasReady <= 1;
							end
							else begin
								counter <= counter + 1;
							end
						end
					end
					else begin
						if(counter == 0) begin
							counter <= 1;
						end
						else begin
							counter <= counter + 1;
						end
					end
				end
			end
			else begin
				if(keyReady) begin
					if(wasReady) begin
						if(BTN_OK[3]) begin
							step <= 1;
							counter <= 0;
							wasReady <= 0;
						end
						else if(BTN_OK[2]) begin
							step <= 2;
							counter <= 0;
							wasReady <= 0;
						end
						else if(BTN_OK[1]) begin
							step <= 4;
							counter <= 0;
							wasReady <= 0;
						end
						else if(BTN_OK[0]) begin
							step <= 8;
							counter <= 0;
							wasReady <= 0;
						end
					end
					else begin
						if(counter == 0) begin
							counter <= 1;
							wasReady <= 1;
						end
						else begin
							counter <= counter + 1;
						end
					end
				end
				else begin
					if(counter == 0) begin
						counter <= 1;
					end
					else begin
						counter <= counter + 1;
					end
				end
			end
		end
	end

	always @(posedge clk or posedge rst) begin
		if(rst) begin
			clkdiv <= 0;
			Clk_CPU <= 0;
			readn <= 0;
		end
		else begin
			if(SW2) begin
				if(SW15) begin
					if(auto_clk) begin
						clkdiv <= clkdiv + 1;
						Clk_CPU <= 1;
						readn <= 1;
					end
					else begin
						clkdiv <= clkdiv + 1;
						Clk_CPU <= 0;
						readn <= 0;
					end
				end
				else begin
					if(auto_clk) begin
						clkdiv <= clkdiv + 1;
						Clk_CPU <= 1;
						readn <= 1;
					end
					else begin
						clkdiv <= clkdiv + 1;
						Clk_CPU <= 0;
						readn <= 0;
					end
				end
			end
			else begin
				if(auto_clk) begin
					clkdiv <= clkdiv + 1;
					Clk_CPU <= 1;
					readn <= 1;
				end
				else begin
					clkdiv <= clkdiv + 1;
					Clk_CPU <= 0;
					readn <= 0;
				end
			end
		end
	end

	always @(posedge clk or posedge rst) begin
		if(rst) begin
			auto_clk <= 0;
		end
		else begin
			if(SW2) begin
				if(SW15) begin
					if(step_reg[24]) begin
						auto_clk <= 1;
					end
					else if(step_reg[4]) begin
						auto_clk <= 1;
					end
					else begin
						auto_clk <= 0;
					end
				end
				else begin
					if(step_reg[24]) begin
						auto_clk <= 1;
					end
					else if(step_reg[4]) begin
						auto_clk <= 1;
					end
					else begin
						auto_clk <= 0;
					end
				end
			end
			else begin
				if(step_reg[24]) begin
					auto_clk <= 1;
				end
				else if(step_reg[4]) begin
					auto_clk <= 1;
				end
				else begin
					auto_clk <= 0;
				end
			end
		end
	end

	assign clkdiv = clkdiv_reg;
	assign Clk_CPU = Clk_CPU_reg;
	assign readn = readn_reg;
endmodule

