module dpram_async
#(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32,
    parameter CLEAR_ON_INIT = 1,
    parameter ENABLE_BYPASS = 1
)
(
    clk,
    rst,
    raddr,
    re,
    waddr,
    we,
    din,
    dout
);


input                           clk;
input                           rst;
input [ADDR_WIDTH-1:0]          raddr;
input                           re;
input [ADDR_WIDTH-1:0]          waddr;
input                           we;
input [DATA_WIDTH-1:0]          din;
output [DATA_WIDTH-1:0]         dout;
reg [DATA_WIDTH-1:0]            mem [0:2**ADDR_WIDTH-1];
reg [DATA_WIDTH-1:0]            dout_reg;

initial
begin
    if (CLEAR_ON_INIT)
    begin
        for (int i = 0; i < 2**ADDR_WIDTH; i = i + 1)
        begin
            mem[i] = 0;
        end
    end
end

always @(*)
begin
    if (ENABLE_BYPASS && re && raddr == waddr)
    begin
        dout_reg = din;
    end
    else
    begin
        dout_reg = mem[raddr];
    end
end

always @(posedge clk)
begin
    if (we)
    begin
        mem[waddr] = din;
    end
end

assign dout = dout_reg;

endmodule

