module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0]last_num;
reg [7:0]last_last_num;
always @(posedge CLK_IN or negedge RST_N) begin
    if(!RST_N) begin
        last_num <= 8'b00000000;
        last_last_num <= 8'b00000000;
    end
    else begin
        last_num <= last_last_num;
        last_last_num <= last_num + last_last_num;
    end
end
assign SEQUENCE = last_num + last_last_num;
endmodule

