module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter INSERT_REGISTER = 1;
 parameter DATA_WIDTH = 32;

 reg [DATA_WIDTH-1:0] r_dataout;
 reg r_dataout_valid;
 reg r_dataout_stall;

 always @(*) begin
  if (INSERT_REGISTER == 1) begin
   if (resetn == 0) begin
    r_dataout <= 0;
    r_dataout_valid <= 0;
    r_dataout_stall <= 0;
   end
   else begin
    if (i_datain_valid == 1) begin
     r_dataout <= i_datain;
     r_dataout_valid <= 1;
     r_dataout_stall <= 0;
    end
    else begin
     r_dataout <= r_dataout;
     r_dataout_valid <= r_dataout_valid;
     r_dataout_stall <= 1;
    end
   end
  end
  else begin
   r_dataout <= i_datain;
   r_dataout_valid <= i_datain_valid;
   r_dataout_stall <= i_datain_valid & i_dataout_stall;
  end
 end

 always @(*) begin
  if (INSERT_REGISTER == 1) begin
   o_datain_stall <= r_dataout_stall;
   o_dataout <= r_dataout;
   o_dataout_valid <= r_dataout_valid;
  end
  else begin
   o_datain_stall <= i_datain_valid & i_dataout_stall;
   o_dataout <= i_datain;
   o_dataout_valid <= i_datain_valid;
  end
 end

endmodule

