module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;

	always @(posedge clk or negedge rst_n)
	begin
		if(!rst_n)
		begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_ok <= 0;
		end
		else
		begin
			if(data_valid)
			begin
				if(data_in_sign)
				begin
					data_reg <= data_reg - data_in;
				end
				else
				begin
					data_reg <= data_reg + data_in;
				end
				data_regnum <= data_regnum + 1;
				if(data_regnum == 8)
				begin
					if(data_reg == 28 || data_reg == 36)
					begin
						data_ok <= 1;
					end
					else
					begin
						data_ok <= 0;
					end
				end
			end
			else
			begin
				data_reg <= 0;
				data_regnum <= 0;
				data_out_sign <= 0;
				data_ok <= 0;
			end
		end
	end
	always @(posedge clk or negedge rst_n)
	begin
		if(!rst_n)
		begin
			data_out <= 0;
			data_out_sign <= 0;
		end
		else
		begin
			if(data_valid)
			begin
				data_out_sign <= 1;
				data_out <= data_out + 1;
			end
			else
			begin
				data_out_sign <= 0;
				data_out <= 0;
			end
		end
	end
endmodule

module counter (rstn, clk, up, down, count); input rstn; input clk; input up; input down; output [WIDTH-1:0] count;
