    if (!rstn) begin
        count_int <= 0;
    end else begin
        if (up) begin
            count_int <= count_int + 1;
        end
        if (down) begin
            count_int <= count_int - 1;
        end
    end
end
assign count = count_int;
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks;
reg clk_out;
  always @(posedge clk_100MHz) begin
    if(~reset) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end
    else begin
      if(ticks == 0) begin
        clk_out <= ~clk_out;
        ticks <= 499999;
      end
      else begin
        ticks <= ticks - 1;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

