    assign s_ready_p1 = s_ready & s_valid & ~load_p1;
    assign s_ready_p2 = s_ready_p1 & ~load_p2;
    assign m_valid_p1 = s_valid & ~load_p1;
    assign m_valid_p2 = s_valid & ~load_p2;
    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
        end else begin
            case (state)
                ZERO: begin
                    if (m_ready) begin
                        state <= ONE;
                    end
                end
                ONE: begin
                    if (m_ready) begin
                        state <= TWO;
                    end
                end
                TWO: begin
                    if (m_ready) begin
                        state <= ZERO;
                    end
                end
                default: begin
                    state <= ZERO;
                end
            endcase
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            case (state)
                ZERO: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
                ONE: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
                TWO: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
                default: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
            endcase
            case (state)
                ZERO: begin
                    if (m_valid_p1) begin
                        load_p1 <= 1'b1;
                    end
                end
                ONE: begin
                    if (m_valid_p1) begin
                        load_p1 <= 1'b1;
                    end
                    if (m_valid_p2) begin
                        load_p2 <= 1'b1;
                    end
                end
                TWO: begin
                    if (m_valid_p1) begin
                        load_p1 <= 1'b1;
                    end
                    if (m_valid_p2) begin
                        load_p2 <= 1'b1;
                    end
                end
                default: begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                end
            endcase
            case (state)
                ZERO: begin
                    if (m_valid_p1) begin
                        load_p1_from_p2 <= 1'b0;
                    end
                end
                ONE: begin
                    if (m_valid_p1) begin
                        load_p1_from_p2 <= 1'b0;
                    end
                    if (m_valid_p2) begin
                        load_p1_from_p2 <= 1'b1;
                    end
                end
                TWO: begin
                    if (m_valid_p1) begin
                        load_p1_from_p2 <= 1'b0;
                    end
                    if (m_valid_p2) begin
                        load_p1_from_p2 <= 1'b1;
                    end
                end
                default: begin
                    load_p1_from_p2 <= 1'b0;
                end
            endcase
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            data_p1 <= 0;
            data_p2 <= 0;
        end else begin
            case (state)
                ZERO: begin
                    if (load_p1) begin
                        data_p1 <= s_data;
                    end
                end
                ONE: begin
                    if (load_p1) begin
                        data_p1 <= s_data;
                    end
                    if (load_p2) begin
                        data_p2 <= s_data;
                    end
                end
                TWO: begin
                    if (load_p1) begin
                        data_p1 <= s_data;
                    end
                    if (load_p2) begin
                        data_p2 <= s_data;
                    end
                end
                default: begin
                    data_p1 <= 0;
                    data_p2 <= 0;
                end
            endcase
        end
    end
    assign s_ready = s_ready_p1 | s_ready_p2;
    assign m_data = data;
    assign m_valid = m_valid_p1 | m_valid_p2;
endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;

always@(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE:
            begin
                if(mode)
                begin
                    counter <= counter + 1;
                    if(mode)
                        state <= INC_STATE;
                end
                else
                begin
                    counter <= counter + 2;
                    state <= INC_STATE;
                end
            end
            INC_STATE:
            begin
                if(mode)
                begin
                    counter <= counter + 1;
                end
                else
                begin
                    counter <= 0;
                    state <= ADD_STATE;
                end
            end
        endcase
    end
end

assign dout = counter;

endmodule

