module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
reg   [1:0]               state, state_n;
reg   [DWIDTH-1:0]        cnt_val, cnt_val_n;
reg                       run, done;

always @(*) begin
    state_n = state;
    cnt_val_n = cnt_val;
    run = 0;
    done = 0;

    case(state)
        S_IDLE: begin
            if (start_i) begin
                state_n = S_RUN;
                cnt_val_n = cnt_val_i;
            end
        end
        S_RUN: begin
            if (cnt_val == cnt_i) begin
                run = 1;
                state_n = S_DONE;
            end
        end
        S_DONE: begin
            done = 1;
            state_n = S_IDLE;
        end
        default: begin
            state_n = S_IDLE;
        end
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        cnt_val <= 0;
    end else begin
        state <= state_n;
        cnt_val <= cnt_val_n;
    end
end

assign run_o = run;
assign done_o = done;

localparam S_IDLE = 2'b00;
localparam S_RUN = 2'b01;
localparam S_DONE = 2'b10;

endmodule

