module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

reg [31:0] len_raw;
reg [31:0] len;
reg [31:0] x_mask;
reg [31:0] f_masked;
reg [31:0] f_incr;
reg [31:0] f_out;
reg [31:0] res;
  always @(posedge clk) begin
    len_raw <= f[30:23] - 255;
    if(len_raw[0] == 1'b1) begin
      len <= 32'h00000001;
    end
    else begin
      len <= 32'h00000000;
    end
    x_mask <= f[30:23] >> len;
    f_masked <= f & ~x_mask;
    f_incr <= f_masked + 1;
    f_out <= f_masked;
    if(f[31] == 1'b1) begin
      f_out <= f_incr;
    end
    res <= {f[31], f[22:23] + len};
    g <= res;
  end
endmodule

