module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [MAX_COUNT-1:0] comp;
    reg [MAX_COUNT-1:0] count;
    assign pulse = comp == 0 && button;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            comp <= MAX_COUNT - 1;
            count <= 0;
        end else begin
            if (button) begin
                count <= count + 1;
                if (count == MIN_COUNT) begin
                    comp <= MAX_COUNT - 1;
                end
            end else begin
                if (comp > MIN_COUNT) begin
                    comp <= comp - DEC_COUNT;
                end
                count <= 0;
            end
        end
    end
endmodule

