module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;
    reg [1:0] state;
    reg [1:0] next;
    reg s_ready_t;

    always @(*) begin
        if (state == ZERO) begin
            if (s_valid) begin
                next = ONE;
            end
            else begin
                next = ZERO;
            end
        end
        else if (state == ONE) begin
            if (m_ready) begin
                next = TWO;
            end
            else begin
                next = ONE;
            end
        end
        else if (state == TWO) begin
            if (s_valid) begin
                next = ONE;
            end
            else begin
                next = TWO;
            end
        end
    end

    always @(*) begin
        if (state == ZERO) begin
            load_p1 = 1'b0;
            load_p2 = 1'b0;
            load_p1_from_p2 = 1'b0;
            s_ready_t = 1'b0;
        end
        else if (state == ONE) begin
            load_p1 = 1'b1;
            load_p2 = 1'b0;
            load_p1_from_p2 = 1'b0;
            s_ready_t = 1'b1;
        end
        else if (state == TWO) begin
            load_p1 = 1'b0;
            load_p2 = 1'b1;
            load_p1_from_p2 = 1'b1;
            s_ready_t = 1'b0;
        end
    end

    always @(*) begin
        if (load_p1) begin
            data_p1 = s_data;
        end
        else if (load_p1_from_p2) begin
            data_p1 = data_p2;
        end
    end

    always @(*) begin
        if (load_p2) begin
            data_p2 = s_data;
        end
    end

    always @(*) begin
        if (state == ZERO) begin
            m_data = 0;
            m_valid = 0;
        end
        else if (state == ONE) begin
            m_data = data_p1;
            m_valid = 1;
        end
        else if (state == TWO) begin
            m_data = data_p2;
            m_valid = 1;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            s_ready <= 1'b0;
        end
        else begin
            state <= next;
            s_ready <= s_ready_t;
        end
    end

endmodule

