module fsm_seq_10010_moore(
    input clk,
    input rst_n,
    input x,
    output z
    );
parameter S1 = 3'b000,
            S2 = 3'b001,
            S3 = 3'b010,
            S4 = 3'b011,
            S5 = 3'b100,
            S6 = 3'b101;

    reg [2:0] state;
    reg [2:0] next;

    always @ (posedge clk or negedge rst_n)
        if (!rst_n)
            state <= S1;
        else
            state <= next;

    always @ (state, x)
        case (state)
            S1: next = x ? S2 : S1;
            S2: next = x ? S3 : S1;
            S3: next = x ? S4 : S1;
            S4: next = x ? S5 : S1;
            S5: next = x ? S6 : S1;
            S6: next = x ? S6 : S1;
            default: next = S1;
        endcase

    assign z = state == S6;

endmodule

