module AND4X4 (IN1,IN2,IN3,IN4,Q);

output  Q;
input   IN1,IN2,IN3,IN4;
and #1 (Q,IN1,IN2,IN3,IN4);

`ifdef functional
`else
specify
specparam in1_lh_q_hl=120,in1_hl_q_hl=120,
in2_lh_q_hl=120,in2_hl_q_hl=120,
in3_lh_q_hl=120,in3_hl_q_hl=120,
in4_lh_q_hl=120,in4_hl_q_hl=120;

(        IN1  => Q) = (in1_lh_q_hl,in1_hl_q_hl);
(        IN2  => Q) = (in2_lh_q_hl,in2_hl_q_hl);
(        IN3  => Q) = (in3_lh_q_hl,in3_hl_q_hl);
(        IN4  => Q) = (in4_lh_q_hl,in4_hl_q_hl);
endspecify
`endif

endmodule

module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg [2:0] SyncA_clkB;
	reg clkA_data;
	reg clkB_data;
	reg FlagToggle_clkA;

	assign FlagOut_clkB = SyncA_clkB[2];
	assign dataB = clkB_data;

	always @(posedge clkA) begin
		clkA_data <= dataA;
		FlagToggle_clkA <= FlagIn_clkA;
	end

	always @(posedge clkB) begin
		if (SyncA_clkB[2] == 1'b0) begin
			clkB_data <= clkA_data;
		end
		if (SyncA_clkB[2] == 1'b1) begin
			clkB_data <= 8'b0;
		end
		if (FlagToggle_clkA == 1'b1) begin
			SyncA_clkB <= {SyncA_clkB[1:0], FlagToggle_clkA};
		end
	end
endmodule

module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
);
wire D_d1;
  wire D_d2;
  wire D_d4;
  wire D_d8;
  wire D_d16;
  wire Q_d1;
  wire Q_d2;
  wire Q_d4;
  wire Q_d8;
  wire Q_d16;
  gh_delay #(
    .DELAY(2)) DLY_0(
    .CLK(CLK),
    .D(D),
    .Q(D_d1));
  gh_delay #(
    .DELAY(4)) DLY_1(
    .CLK(CLK),
    .D(D_d1),
    .Q(D_d2));
  gh_delay #(
    .DELAY(8)) DLY_2(
    .CLK(CLK),
    .D(D_d2),
    .Q(D_d4));
  gh_delay #(
    .DELAY(16)) DLY_3(
    .CLK(CLK),
    .D(D_d4),
    .Q(D_d8));
  gh_delay #(
    .DELAY(31)) DLY_4(
    .CLK(CLK),
    .D(D_d8),
    .Q(D_d16));
  assign Q_d1 = D;
  assign Q_d2 = D_d1;
  assign Q_d4 = D_d2;
  assign Q_d8 = D_d4;
  assign Q_d16 = D_d8;
  assign Q = DELAY[0] ? D : DELAY[1] ? D_d1 : DELAY[2] ? D_d2 : DELAY[3] ? D_d4 : DELAY[4] ? D_d8 : DELAY[5] ? D_d16 : D;
endmodule

module mulor_3_stage_signed_10_bit(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	output [9:0] out,
	input clk);
logic signed [19:0] stage0;
	logic signed [19:0] stage1;
	logic signed [19:0] stage2;

	always @(posedge clk) begin
	stage0 <= (a * b) | c;
	stage1 <= stage0;
	stage2 <= stage1;
	end

	assign out = stage2;
endmodule

