module testbench;
reg [2:0] A;
reg [2:0] B;
wire A_greater;
wire A_equal;
wire A_less;

comparator_3bit comparator_3bit_inst(A, B, A_greater, A_equal, A_less);

initial begin
    integer i;
    integer error = 0;
    for (i = 0; i < 100; i = i + 1) begin
        A = $random;
        B = $random;
        if (A > B) begin
            if (A_greater == 0) begin
                $display("Error: A_greater = 0, but A > B");
                error = error + 1;
            end
        end
        if (A < B) begin
            if (A_less == 0) begin
                $display("Error: A_less = 0, but A < B");
                error = error + 1;
            end
        end
        if (A == B) begin
            if (A_equal == 0) begin
                $display("Error: A_equal = 0, but A == B");
                error = error + 1;
            end
        end
    end
    if (error == 0) begin
        $display("Test passed");
    end
    else begin
        $display("Test failed");
        $display("Number of errors: %d", error);
    end
end
endmodule

