module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h12345678;
    reg [31:0] M_x;
    reg [31:0] M_y;
    reg [31:0] M_z;
    reg [31:0] M_w;
    reg [31:0] M_w_d;
    reg [31:0] M_x_q;
    reg [31:0] M_y_q;
    reg [31:0] M_z_q;
    reg [31:0] M_w_q;
    reg [31:0] t;
    always @ (posedge clk) begin
        M_x <= M_x_q;
        M_y <= M_y_q;
        M_z <= M_z_q;
        M_w <= M_w_q;
    end
    always @ (posedge clk) begin
        M_x_q <= M_x;
        M_y_q <= M_y;
        M_z_q <= M_z;
        M_w_q <= M_w;
    end
    always @ (posedge clk) begin
        if (rst) begin
            M_w_d <= {32{1'b0}};
            M_w_d[31:0] <= seed;
        end
        else begin
            M_w_d <= {32{1'b0}};
            M_w_d[31:0] <= M_w;
        end
    end
    always @ (posedge clk) begin
        t <= M_x_q[31:0] ^ M_y_q[31:0] ^ M_z_q[31:0];
    end
    always @ (posedge clk) begin
        M_x <= M_y_q;
        M_y <= M_z_q;
        M_z <= M_w_q;
        M_w <= M_w_d ^ t;
    end
    assign num = M_w_q;
endmodule

module submuland_2_stage_unsigned_10_bit(
