module adder_word(	input wire [31:0] a,
			input wire [31:0] b,
			input wire carry_in,
			output wire [31:0] sum,
			output wire carry_out);
wire [7:0] tmp_carry;
	assign tmp_carry[0] = carry_in;
	assign tmp_carry[1] = adder_8bit(a[7:0], b[7:0], tmp_carry[0]).carry_out;
	assign tmp_carry[2] = adder_8bit(a[15:8], b[15:8], tmp_carry[1]).carry_out;
	assign tmp_carry[3] = adder_8bit(a[23:16], b[23:16], tmp_carry[2]).carry_out;
	assign tmp_carry[4] = adder_8bit(a[31:24], b[31:24], tmp_carry[3]).carry_out;
	assign sum[7:0] = adder_8bit(a[7:0], b[7:0], tmp_carry[0]).sum;
	assign sum[15:8] = adder_8bit(a[15:8], b[15:8], tmp_carry[1]).sum;
	assign sum[23:16] = adder_8bit(a[23:16], b[23:16], tmp_carry[2]).sum;
	assign sum[31:24] = adder_8bit(a[31:24], b[31:24], tmp_carry[3]).sum;
	assign carry_out = tmp_carry[4];
endmodule

