module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [1:0] state;
parameter [1:0] s0=2'b00, s1=2'b01, s2=2'b10, s3=2'b11;
assign red = state[0];
assign yellow = state[1];
assign green = state[0] ^ state[1];
always @(posedge clk or posedge reset) begin
	if (reset) state <= s0;
	else begin
		case (state)
			s0: state <= s1;
			s1: state <= s2;
			s2: state <= s3;
			s3: state <= s0;
		endcase
	end
end
endmodule

