endmodule

module soundcodec(
	input	clk,
   input pulse,
   output o_pwm
);
reg [8:0] PWM_accumulator;
   reg PWM_state;
   always @(posedge clk) begin
      case (PWM_state)
         0: begin
            if (pulse) begin
               PWM_accumulator <= PWM_accumulator + 255;
            end
            PWM_state <= 1;
         end
         1: begin
            PWM_state <= 0;
         end
      endcase
   end
   assign o_pwm = PWM_accumulator[8];
endmodule

