module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
reg [2:0] state;
  always @(posedge PCLK) begin
    if (!PRESETn) begin
      state <= IDLE;
    end
    else begin
      case (state)
        IDLE: begin
          if (Transfer) begin
            state <= SETUP;
          end
        end
        SETUP: begin
          if (PREADY) begin
            state <= ACCESS;
          end
        end
        ACCESS: begin
          if (Transfer) begin
            state <= SETUP;
          end
          else if (PSLVERR) begin
            state <= IDLE;
          end
          else if (PREADY) begin
            state <= ACCESS;
          end
        end
      endcase
    end
  end
  always @(state) begin
    case (state)
      IDLE: begin
        PSELx <= 1'b0;
        PENABLE <= 1'b0;
        PWRITE <= 1'b0;
        PADDR <= 5'b0;
        PWDATA <= 32'b0;
      end
      SETUP: begin
        PSELx <= 1'b1;
        PENABLE <= 1'b1;
        PWRITE <= Wr_Rd;
        PADDR <= Address;
        PWDATA <= write_data;
      end
      ACCESS: begin
        PSELx <= 1'b1;
        PENABLE <= 1'b1;
        PWRITE <= Wr_Rd;
        PADDR <= Address;
        PWDATA <= write_data;
      end
    endcase
  end
  always @(state) begin
    case (state)
      IDLE: begin
        read_data <= 32'b0;
      end
      SETUP: begin
        read_data <= 32'b0;
      end
      ACCESS: begin
        if (Wr_Rd) begin
          read_data <= 32'b0;
        end
        else if (PREADY) begin
          read_data <= PRDATA;
        end
      end
    endcase
  end
endmodule

module FIFO_arp_server_arpTableInsertFifo_V_shiftReg (
