module FIFO_toe_ackDelayFifoReadCount_V_V (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output[DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;
parameter DATA_WIDTH = 32'd32;
parameter ADDR_WIDTH = 32'd10;
parameter MEMORY_STYLE = "distributed";
parameter DEPTH = 32'd1024;

reg[DATA_WIDTH - 1:0] shift_reg[0:DEPTH - 1];
reg[ADDR_WIDTH - 1:0] read_ptr;
reg[ADDR_WIDTH - 1:0] write_ptr;
reg if_empty_n;
reg if_full_n;

always @(posedge clk) begin
    if (reset) begin
        if_empty_n <= 1'b0;
        if_full_n <= 1'b0;
        read_ptr <= 0;
        write_ptr <= 0;
    end else begin
        if (if_write_ce) begin
            if (if_write) begin
                if (write_ptr < DEPTH - 1) begin
                    write_ptr <= write_ptr + 1;
                end
                else begin
                    write_ptr <= 0;
                end
            end
        end
        if (if_read_ce) begin
            if (if_read) begin
                if (read_ptr > 0) begin
                    read_ptr <= read_ptr - 1;
                end
                else begin
                    read_ptr <= DEPTH - 1;
                end
            end
        end
        if (if_write_ce) begin
            if (if_write) begin
                if (write_ptr == read_ptr) begin
                    if_empty_n <= 1'b0;
                end
                else begin
                    if_empty_n <= 1'b1;
                end
            end
        end
        if (if_read_ce) begin
            if (if_read) begin
                if (write_ptr == read_ptr) begin
                    if_full_n <= 1'b0;
                end
                else begin
                    if_full_n <= 1'b1;
                end
            end
        end
    end
end

assign if_dout = shift_reg[read_ptr];

endmodule

