module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] upper_bound = 32'd100000000;
reg [27:0] count = 0;
  always @(posedge clk) begin
    if(count == upper_bound) begin
      count <= 0;
      pulse <= 1;
    end
    else begin
      count <= count + 1;
      pulse <= 0;
    end
  end
endmodule

