module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
wire  mainclk_tmp;
wire  updateclk_tmp;
wire  capture_tmp;
wire  update_tmp;
wire  clk_tmp;
wire  shiftnld_tmp;
wire  captnupdt_tmp;

assign mainclk = mainclk_tmp & 1'b1;
assign updateclk = updateclk_tmp & 1'b1;
assign capture = capture_tmp & 1'b1;
assign update = update_tmp & 1'b1;

always @(*) begin
    mainclk_tmp = 0;
    updateclk_tmp = 0;
    capture_tmp = 0;
    update_tmp = 0;
    clk_tmp = clk;
    shiftnld_tmp = shiftnld;
    captnupdt_tmp = captnupdt;
    case ({captnupdt_tmp, shiftnld_tmp})
        2'b00: begin
            mainclk_tmp = 0;
            updateclk_tmp = 0;
            capture_tmp = 0;
            update_tmp = 0;
        end
        2'b01: begin
            mainclk_tmp = 0;
            updateclk_tmp = 0;
            capture_tmp = 0;
            update_tmp = 0;
        end
        2'b10: begin
            mainclk_tmp = 0;
            updateclk_tmp = 0;
            capture_tmp = 0;
            update_tmp = 0;
        end
        2'b11: begin
            mainclk_tmp = 0;
            updateclk_tmp = 0;
            capture_tmp = 0;
            update_tmp = 0;
        end
    endcase
end

endmodule

