module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [inputWidth-1:0] maxValue;
reg [(numInput*inputWidth)-1:0] inDataBuffer;
reg [31:0] counter;
always@(posedge i_clk)
begin
    if(i_valid)
    begin
        maxValue = 0;
        inDataBuffer = 0;
        counter = 0;
        o_data_valid = 0;
    end
    else
    begin
        if(counter < numInput)
        begin
            maxValue = maxValue > inDataBuffer[(counter*inputWidth)+:inputWidth] ? maxValue : inDataBuffer[(counter*inputWidth)+:inputWidth];
            counter = counter + 1;
        end
        else
        begin
            o_data = maxValue;
            o_data_valid = 1;
        end
    end
end
endmodule

