module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg     [63:0] value;
  reg     [63:0] state;
  reg     [63:0] s_input_a_ack;

  initial
    begin
      state = 0;
      s_input_a_ack = 0;
      input_a_ack = 0;
    end

  always @(posedge clk)
    begin
      case (state)
        0: begin
            if (input_a_stb)
              begin
                value = input_a;
                state = 1;
              end
            else
              begin
                state = 0;
              end
          end
        1: begin
            $fopena("resp_z");
            $fdisplay("resp_z",value[63:32]);
            $fdisplay("resp_z",value[31:0]);
            $fclose("resp_z");
            state = 0;
            s_input_a_ack = 1;
          end
        default: begin
            state = 0;
          end
      endcase
    end

  always @(posedge clk)
    begin
      if (rst)
        begin
          s_input_a_ack = 0;
        end
      else
        begin
          s_input_a_ack = 1;
        end
    end

  assign input_a_ack = s_input_a_ack;

endmodule

