module lfsr    (
out             ,  
enable          ,  
clk             ,  
reset              
);


output [7:0] out;

input enable, clk, reset;
wire [7:0] out;
wire linear_feedback;

assign linear_feedback = ~ (out[7] ^ out[3]);

always @(posedge clk) begin
    if (reset) begin
        out <= 8'b00000000;
    end else if (enable) begin
        out <= {out[6:0], linear_feedback};
    end
end

endmodule

