endmodule

module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
parameter Baud = 115200;
parameter Oversampling = 100000000 / Baud / Oversampling;
parameter log2 = $clog2(Oversampling);

reg [log2:0] Acc;
wire [log2:0] Inc = Oversampling / 2;

always @(posedge clk) begin
	if (enable) begin
		Acc <= Acc + Inc;
	end else begin
		Acc <= 0;
	end
end

assign tick = Acc[log2];

endmodule

module f9_NegEdgeClock(q, d, clk, reset);
