endmodule

module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter [9:0] TOTAL_COLUMNS = 640;
parameter [9:0] TOTAL_ROWS = 480;
parameter [9:0] ACTIVE_COLUMNS = 640;
parameter [9:0] ACTIVE_ROWS = 480;
parameter [9:0] HSYNC_WIDTH = 9;
parameter [9:0] HSYNC_BLANK = 9;
parameter [9:0] VSYNC_WIDTH = 9;
parameter [9:0] VSYNC_BLANK = 9;
parameter [9:0] HSYNC_START = 0;
parameter [9:0] HSYNC_END = HSYNC_START + HSYNC_WIDTH;
parameter [9:0] VSYNC_START = 0;
parameter [9:0] VSYNC_END = VSYNC_START + VSYNC_WIDTH;
parameter [9:0] ACTIVE_START = HSYNC_END + HSYNC_BLANK;
parameter [9:0] ACTIVE_END = ACTIVE_START + ACTIVE_COLUMNS;
parameter [9:0] ACTIVE_ROW_START = 0;
parameter [9:0] ACTIVE_ROW_END = ACTIVE_ROW_START + ACTIVE_ROWS;
parameter [9:0] TOTAL_START = ACTIVE_ROW_END + VSYNC_BLANK;
parameter [9:0] TOTAL_END = TOTAL_START + TOTAL_COLUMNS;

assign o_hsync = (o_col_count >= ACTIVE_START && o_col_count < ACTIVE_END) ? 1'b0 : 1'b1;
assign o_vsync = (o_row_count >= ACTIVE_ROW_START && o_row_count < ACTIVE_ROW_END) ? 1'b0 : 1'b1;

always @(posedge i_clk) begin
    if (o_col_count == TOTAL_COLUMNS) begin
        o_col_count <= 0;
    end
    else begin
        o_col_count <= o_col_count + 1;
    end
    if (o_row_count == TOTAL_ROWS) begin
        o_row_count <= 0;
    end
    else begin
        o_row_count <= o_row_count + 1;
    end
end

endmodule

