module bridge_1x2(                                 
    input                           clk,          
    input                           resetn,       
    input                           cpu_data_en,      
    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
parameter CONF_ADDR_BASE = 32'h00000000;
parameter CONF_ADDR_MASK = 32'h00000000;

reg [3:0] sel_sram;
reg [3:0] sel_conf;

always @(posedge clk) begin
    if (resetn == 1'b0) begin
        sel_sram <= 4'b0000;
        sel_conf <= 4'b0000;
    end else begin
        if (cpu_data_addr[31:28] == CONF_ADDR_BASE[31:28]) begin
            sel_conf <= cpu_data_addr[27:24];
        end else begin
            sel_sram <= cpu_data_addr[27:24];
        end
    end
end

assign data_sram_en = cpu_data_en & (sel_sram == 4'b0000);
assign data_sram_wen = cpu_data_en & (sel_sram == 4'b0000) & cpu_data_wen;
assign data_sram_addr = cpu_data_addr[27:0];
assign data_sram_wdata = cpu_data_wdata;
assign cpu_data_rdata = (sel_sram == 4'b0000) ? data_sram_rdata : conf_rdata;

assign conf_en = cpu_data_en & (sel_conf == 4'b0000);
assign conf_wen = cpu_data_en & (sel_conf == 4'b0000) & cpu_data_wen;
assign conf_addr = cpu_data_addr[27:0];
assign conf_wdata = cpu_data_wdata;

endmodule

