module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [0 : 15];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock) begin
        if (sclr) begin
            wp <= 0;
            rp <= 0;
            w_flag <= 0;
            r_flag <= 0;
        end
        else begin
            if (wrreq) begin
                if (w_flag) begin
                    mem[wp] <= data;
                    wp <= wp + 1;
                    w_flag <= 0;
                end
                else begin
                    mem[wp] <= data;
                    w_flag <= 1;
                end
            end
            if (rdreq) begin
                if (r_flag) begin
                    rp <= rp + 1;
                    r_flag <= 0;
                end
                else begin
                    rp <= rp + 1;
                    r_flag <= 1;
                end
            end
        end
    end
    always @(posedge clock) begin
        if (sclr) begin
            full <= 0;
            empty <= 0;
        end
        else begin
            if (w_flag) begin
                if (r_flag) begin
                    if (wp == rp) begin
                        full <= 1;
                        empty <= 1;
                    end
                    else begin
                        full <= 0;
                        empty <= 0;
                    end
                end
                else begin
                    if (wp == rp) begin
                        full <= 1;
                        empty <= 0;
                    end
                    else begin
                        full <= 0;
                        empty <= 0;
                    end
                end
            end
            else begin
                if (r_flag) begin
                    if (wp == rp) begin
                        full <= 0;
                        empty <= 1;
                    end
                    else begin
                        full <= 0;
                        empty <= 0;
                    end
                end
                else begin
                    if (wp == rp) begin
                        full <= 0;
                        empty <= 1;
                    end
                    else begin
                        full <= 0;
                        empty <= 0;
                    end
                end
            end
        end
    end
    assign q = mem[rp];
endmodule

