module AdderTreePipelined
#(
    parameter DATA_WIDTH=32,
    parameter LENGTH=8,
    parameter OUT_WIDTH=DATA_WIDTH+$clog2(LENGTH),
    parameter DELAT_STAGES=$clog2(LENGTH)
)
(
    input rst,
    input clk,
    input in_advance,
    input signed [LENGTH*DATA_WIDTH-1:0] in_addends,
    output signed [OUT_WIDTH-1:0] out_sum
);
if (LENGTH == 1)
    begin
        if (DELAT_STAGES == 0)
            begin
                assign out_sum = in_addends;
            end
        else
            begin
                assign out_sum = in_addends;
                assign out_sum = {out_sum[DATA_WIDTH-1:0], {DELAT_STAGES{1'b0}}};
            end
    end
else
    begin
        wire signed [LENGTH*DATA_WIDTH/2-1:0] in_addends_0;
        wire signed [LENGTH*DATA_WIDTH/2-1:0] in_addends_1;
        wire signed [OUT_WIDTH-1:0] out_sum_0;
        wire signed [OUT_WIDTH-1:0] out_sum_1;
        assign in_addends_0 = in_addends[LENGTH*DATA_WIDTH/2-1:0];
        assign in_addends_1 = in_addends[LENGTH*DATA_WIDTH-1:LENGTH*DATA_WIDTH/2];
        AdderTreePipelined
        #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        )
        adder_tree_0
        (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(in_addends_0),
            .out_sum(out_sum_0)
        );
        AdderTreePipelined
        #(
            .DATA_WIDTH(DATA_WIDTH),
            .LENGTH(LENGTH/2),
            .OUT_WIDTH(OUT_WIDTH),
            .DELAT_STAGES(DELAT_STAGES)
        )
        adder_tree_1
        (
            .rst(rst),
            .clk(clk),
            .in_advance(in_advance),
            .in_addends(in_addends_1),
            .out_sum(out_sum_1)
        );
        assign out_sum = out_sum_0 + out_sum_1;
    end
endmodule

