module timer_variable(
input wire zedboard_clk,
input wire enable,
input wire reset,
output reg timerOutput
); 

reg [31:0] timer_value;
  always @(posedge zedboard_clk) begin
    if(reset == 1'b1) begin
      timer_value <= 0;
    end
    else if(timer_value == 100000) begin
      timer_value <= 0;
      timerOutput <= 1'b1;
    end
    else begin
      timer_value <= timer_value + 1;
      timerOutput <= 1'b0;
    end
  end
endmodule

module NAND3xp33_ASAP7_75t_R (Y, A, B, C);
output Y;
input A, B, C;
not (notC, C);
  not (notB, B);
  not (notA, A);
  or (Y, notA, notB, notC);
  specify
    specparam
      tplh$A$Y = 1.0,
      tphl$A$Y = 1.0,
      tplh$B$Y = 1.0,
      tphl$B$Y = 1.0,
      tplh$C$Y = 1.0,
      tphl$C$Y = 1.0;

    (A *> Y) = (tplh$A$Y, tphl$A$Y);
    (B *> Y) = (tplh$B$Y, tphl$B$Y);
    (C *> Y) = (tplh$C$Y, tphl$C$Y);
  endspecify
endmodule

