module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    if (J & K)
        Q <= ~Q;
    else if (J)
        Q <= 1;
    else if (K)
        Q <= 0;
    Qbar <= ~Q;
endmodule

module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);
logic [10:0] rom_addr;
logic [3:0] rom_data;
logic [3:0] palette_red, palette_green, palette_blue;

