assign green = blank ? palette_green : 4'h0;
assign blue = blank ? palette_blue : 4'h0;

Walk2R_rom rom (vga_clk, rom_addr, rom_data);
Walk2R_palette palette (rom_data, palette_red, palette_green, palette_blue);

endmodule

