module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

reg [31:0] x_0;
  reg [31:0] x_i;
  reg [31:0] x_i_mux;
  reg [31:0] x_next;
  reg [31:0] sqrt;
  reg [31:0] out_sqrt_reg;
  reg val_comb;
  reg z_comb;
  reg val_ff;
  reg z_ff;
  assign x_0 = 32'h100000000;
  assign x_i_mux = SEL ? x_next : x_i;
  assign x_next = x_i_mux + (n / x_i_mux);
  assign sqrt = x_i_mux;
  assign out_sqrt = out_sqrt_reg;
  assign VAL = val_comb;
  assign Z = z_comb;
  always @(posedge CLK) begin
    if((RST_n == 1'b0)) begin
      x_i <= 32'h0;
      out_sqrt_reg <= 32'h0;
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        if((n == 32'h0)) begin
          out_sqrt_reg <= 32'h0;
          val_ff <= 1'b0;
          z_ff <= 1'b1;
        end
        else begin
          if((x_next >= x_i)) begin
            out_sqrt_reg <= x_i;
            val_ff <= 1'b1;
            z_ff <= 1'b0;
          end
          else begin
            val_ff <= 1'b0;
            z_ff <= 1'b0;
          end
        end
      end
      x_i <= x_i_mux;
      val_comb <= val_ff;
      z_comb <= z_ff;
    end
  end
endmodule

