module delay (
	input clk,
	input reset,
	input [3:0] variable_pulse_index,
	output slow_pulse,
	output fast_pulse,
	output variable_pulse
);
reg [31:0] counter;
	parameter MAX = 24000000;
	parameter BASE = 2000000;
	parameter SLOW = 18000000;
	parameter FAST = 4800000;
	parameter VAR = 1000000;
	parameter VAR_MAX = 24000000;
	parameter VAR_BASE = 2000000;
	parameter VAR_THRESHOLD = VAR_BASE * (VAR_MAX - variable_pulse_index) / VAR_MAX;
	assign slow_pulse = (counter >= SLOW);
	assign fast_pulse = (counter >= FAST);
	assign variable_pulse = (counter >= VAR_THRESHOLD);
	always @(posedge clk) begin
		if (reset) begin
			counter <= 0;
		end
		else begin
			counter <= counter + 1;
		end
	end
endmodule

