module chose(output reg [17:0]choout,
				input [16:0]choin,
				input resreg,
				input clk);
always@(posedge clk)
	begin
		if(resreg==1'b0)
			choout<=choin;
		else
			begin
				reg [16:0]chotmp;
				chotmp<=~choin[15:0];
				chotmp<=chotmp+1;
				choout[15:0]<=chotmp;
				choout[16]<=~choin[15];
				choout[17]<=~choin[15];
			end
	end
endmodule

