module clock_divider(clock_in,clock_out
    );
input clock_in; 
output reg clock_out;
parameter DIVISOR = 1000000000;
parameter WIDTH = 28;
reg [WIDTH-1:0] counter = 0;
always @(posedge clock_in) begin
    if(counter < DIVISOR-1) begin
        counter = counter + 1;
    end
    else begin
        counter = 0;
    end
    if(counter < DIVISOR/2) begin
        clock_out = 1;
    end
    else begin
        clock_out = 0;
    end
end
endmodule

