module division(A,B,Res);
    input [WIDTH-1:0] A;
    input [WIDTH-1:0] B;

    output reg [WIDTH-1:0] Res = 0;
parameter WIDTH = 16;
    reg [WIDTH-1:0] a1 = 0;
    reg [WIDTH-1:0] b1 = 0;
    reg [WIDTH:0] p1 = 0;
    always @(A or B)
    begin
        a1 = A;
        b1 = B;
        p1 = 0;
        for (int i = 0; i < WIDTH; i = i + 1)
        begin
            p1 = p1 << 1;
            if (a1 >= b1)
