module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] H_ACTIVE = 640;
parameter [31:0] H_SYNC = 96;
parameter [31:0] H_BACK = 48;
parameter [31:0] H_RETRACE = 48;
parameter [31:0] V_ACTIVE = 480;
parameter [31:0] V_SYNC = 2;
parameter [31:0] V_BACK = 33;
parameter [31:0] V_RETRACE = 33;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
always @(posedge clk) begin
    if(rst) begin
        h_count_reg <= 0;
        v_count_reg <= 0;
    end else begin
        if(h_count_reg < H_ACTIVE) begin
            h_count_reg <= h_count_reg + 1;
        end else begin
            h_count_reg <= 0;
            if(v_count_reg < V_ACTIVE) begin
                v_count_reg <= v_count_reg + 1;
            end else begin
                v_count_reg <= 0;
            end
        end
    end
end
assign xaddr = h_count_reg;
assign yaddr = v_count_reg;
assign active = (h_count_reg < H_ACTIVE) && (v_count_reg < V_ACTIVE);
assign hsync = (h_count_reg < H_ACTIVE) && (h_count_reg >= H_ACTIVE - H_SYNC) && (h_count_reg < H_ACTIVE - H_SYNC + H_BACK);
assign vsync = (v_count_reg < V_ACTIVE) && (v_count_reg >= V_ACTIVE - V_SYNC) && (v_count_reg < V_ACTIVE - V_SYNC + V_BACK);
endmodule

