module TopModule(
    input  clk,
    input  resetn,
    input  r (3 bits),
    output g (3 bits)
);
parameter [1:0] A = 0;
parameter [1:0] B = 1;
parameter [1:0] C = 2;
parameter [1:0] D = 3;

reg [1:0] state;
assign g[0] = (state == B) ? 1 : 0;
assign g[1] = (state == C) ? 1 : 0;
assign g[2] = (state == D) ? 1 : 0;

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        state <= A;
    end else begin
        case (state)
            A: begin
                if (r[0] == 1) begin
                    state <= B;
                end
                else if (r[1] == 1) begin
                    state <= C;
                end
                else if (r[2] == 1) begin
                    state <= D;
                end
                else begin
                    state <= A;
                end
            end
            B: begin
                if (r[0] == 1) begin
                    state <= B;
                end
                else begin
                    state <= A;
                end
            end
            C: begin
                if (r[1] == 1) begin
                    state <= C;
                end
                else begin
                    state <= A;
                end
            end
            D: begin
                state <= A;
            end
        endcase
    end
end

endmodule

