module TopModule(
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);
parameter [1:0] IDLE = 2'b00;
parameter [1:0] START = 2'b01;
parameter [1:0] COUNTING = 2'b10;
parameter [1:0] DONE = 2'b11;

reg [1:0] state;
reg [1:0] next_state;
reg [1:0] count;
reg [1:0] count_next;
reg [1:0] shift_ena_reg;
reg [1:0] shift_ena_next;
reg [1:0] counting_reg;
reg [1:0] counting_next;
reg [1:0] done_reg;
reg [1:0] done_next;

assign shift_ena = shift_ena_reg;
assign counting = counting_reg;
assign done = done_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        count <= 0;
        shift_ena_reg <= 0;
        counting_reg <= 0;
        done_reg <= 0;
    end
    else begin
        state <= next_state;
        count <= count_next;
        shift_ena_reg <= shift_ena_next;
        counting_reg <= counting_next;
        done_reg <= done_next;
    end
end

always @(state, data, count) begin
    case (state)
        IDLE: begin
            if (data == 4'b1101) begin
                next_state = START;
                count_next = 0;
            end
            else begin
                next_state = IDLE;
                count_next = 0;
            end
        end
        START: begin
            if (data == 4'b1101) begin
                next_state = START;
                count_next = 0;
            end
            else begin
                next_state = COUNTING;
                count_next = 0;
            end
        end
        COUNTING: begin
            if (data == 4'b1101) begin
                next_state = COUNTING;
                count_next = count + 1;
            end
            else begin
                next_state = COUNTING;
                count_next = count + 1;
            end
        end
        DONE: begin
            if (data == 4'b1101) begin
                next_state = DONE;
                count_next = 0;
            end
            else begin
                next_state = IDLE;
                count_next = 0;
            end
        end
        default: begin
            next_state = IDLE;
            count_next = 0;
        end
    endcase
end

always @(state, count) begin
    case (state)
        IDLE: begin
            shift_ena_next = 0;
            counting_next = 0;
            done_next = 0;
        end
        START: begin
            shift_ena_next = 0;
            counting_next = 0;
            done_next = 0;
        end
        COUNTING: begin
            if (count == 3) begin
                shift_ena_next = 1;
                counting_next = 1;
                done_next = 0;
            end
            else begin
                shift_ena_next = 0;
                counting_next = 1;
                done_next = 0;
            end
        end
        DONE: begin
            shift_ena_next = 0;
            counting_next = 0;
            done_next = 1;
        end
        default: begin
            shift_ena_next = 0;
            counting_next = 0;
            done_next = 0;
        end
    endcase
end

endmodule

