  input resetn,
  input  [2:0] r,
  output [2:0] g
);
parameter [1:0] A = 0,
                 B = 1,
                 C = 2,
                 D = 3;

  reg [1:0] state;

  always @(posedge clk) begin
    if (!resetn) begin
      state <= A;
    end else begin
      case (state)
        A: if (r[0] == 0 && r[1] == 0 && r[2] == 0) begin
            state <= A;
          end else if (r[0] == 1) begin
            state <= B;
          end else if (r[0] == 0 && r[1] == 1) begin
            state <= C;
          end else if (r[0] == 0 && r[1] == 0 && r[2] == 1) begin
            state <= D;
          end
        B: if (r[0] == 1) begin
            state <= B;
          end else if (r[0] == 0) begin
            state <= A;
          end
        C: if (r[1] == 1) begin
            state <= C;
          end else if (r[1] == 0) begin
            state <= A;
          end
        D: state <= A;
      endcase
    end
  end

  always @(state) begin
    case (state)
      A: begin
          g[0] <= 0;
          g[1] <= 0;
          g[2] <= 0;
        end
      B: begin
          g[0] <= 1;
          g[1] <= 0;
          g[2] <= 0;
